"""How views are built and written from the source file."""

import json
import os
import shutil
import stat
import subprocess
import sys
import tempfile
import unittest

PROJECT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
HEADER = (
    "<!-- Generated from org.json by render.py. Do not edit this file: "
    "change org.json, then run python3 render.py -->"
)


def sample():
    """A small valid org used as a starting point."""
    return {
        "org": "Fixture Co",
        "people": ["Nia", "Omar", "Pip"],
        "teams": [
            {
                "name": "Trade",
                "head": "Omar",
                "measured_by": "deals that were signed",
                "owns": ["the alder log"],
            },
            {
                "name": "Make",
                "head": "Nia",
                "measured_by": "ships that land",
                "owns": ["the cedar log"],
            },
            {
                "name": "Keep",
                "head": "Pip",
                "measured_by": "nights the store was checked",
                "members": ["Omar"],
            },
        ],
        "outputs": [
            {"view": "roster", "file": "ROSTER.md"},
            {"view": "owners", "file": "OWNERS.md"},
        ],
    }


class RenderTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.mkdtemp(prefix="org-chart-render-")
        self.addCleanup(shutil.rmtree, self.tmp)

    def write_org(self, data):
        with open(os.path.join(self.tmp, "org.json"), "w", encoding="utf-8", newline="\n") as handle:
            json.dump(data, handle)
            handle.write("\n")

    def run_render(self, script, *args, cwd=None, umask=None):
        env = os.environ.copy()
        env["HOME"] = self.tmp
        env["PYTHONDONTWRITEBYTECODE"] = "1"
        env.pop("PYTHONPATH", None)
        command = [sys.executable, script, *args, "--root", self.tmp]
        if umask is not None:
            command = ["/bin/sh", "-c", 'umask %s; exec "$@"' % umask, "sh"] + command
        return subprocess.run(
            command,
            cwd=cwd or self.tmp,
            env=env,
            capture_output=True,
            text=True,
        )

    def render(self, *args, cwd=None, umask=None):
        return self.run_render(os.path.join(PROJECT, "render.py"), *args, cwd=cwd, umask=umask)

    def render_temps(self):
        found = []
        for dirpath, _dirnames, filenames in os.walk(self.tmp):
            for name in filenames:
                if name.startswith(".render-"):
                    found.append(os.path.join(dirpath, name))
        return found

    def test_second_run_reports_unchanged(self):
        """source: a second run writes nothing new and says each output is unchanged"""
        self.write_org(sample())
        first = self.render()
        self.assertEqual(first.returncode, 0, first.stdout)
        self.assertIn("wrote ROSTER.md", first.stdout)
        self.assertIn("wrote OWNERS.md", first.stdout)
        second = self.render()
        self.assertEqual(second.returncode, 0, second.stdout)
        self.assertIn("unchanged ROSTER.md", second.stdout)
        self.assertIn("unchanged OWNERS.md", second.stdout)
        self.assertIn("(0 changed)", second.stdout)

    def test_roster_follows_source_order(self):
        """source: the roster lists teams in the order of the source file"""
        self.write_org(sample())
        proc = self.render("--view", "roster")
        self.assertEqual(proc.returncode, 0, proc.stdout)
        self.assertLess(proc.stdout.index("| Trade |"), proc.stdout.index("| Make |"))
        self.assertLess(proc.stdout.index("| Make |"), proc.stdout.index("| Keep |"))
        self.assertNotIn("<!--", proc.stdout)

    def test_owners_are_alphabetical(self):
        """source: owned things are listed in alphabetical order without regard to case"""
        self.write_org(sample())
        proc = self.render("--view", "owners")
        self.assertEqual(proc.returncode, 0, proc.stdout)
        self.assertLess(proc.stdout.index("the alder log"), proc.stdout.index("the cedar log"))
        self.assertIn("- the alder log: Trade (Omar)", proc.stdout)

    def test_empty_member_column_is_left_out(self):
        """source: the members column is left out when no team has members"""
        data = sample()
        for team in data["teams"]:
            team.pop("members", None)
        self.write_org(data)
        proc = self.render("--view", "roster")
        self.assertEqual(proc.returncode, 0, proc.stdout)
        self.assertNotIn("Members", proc.stdout)
        self.assertIn("Measured by", proc.stdout)

    def test_empty_owns_column_is_left_out(self):
        """source: the owns column is left out when no team owns anything"""
        data = sample()
        for team in data["teams"]:
            team.pop("owns", None)
        data["outputs"] = [{"view": "roster", "file": "ROSTER.md"}]
        self.write_org(data)
        proc = self.render("--view", "roster")
        self.assertEqual(proc.returncode, 0, proc.stdout)
        self.assertNotIn("Owns", proc.stdout)

    def test_pipe_in_a_cell_is_escaped(self):
        """source: a vertical bar inside a value must not break the table"""
        data = sample()
        data["teams"][0]["measured_by"] = "one | two"
        self.write_org(data)
        proc = self.render("--view", "roster")
        self.assertEqual(proc.returncode, 0, proc.stdout)
        self.assertIn("one \\| two", proc.stdout)

    def test_whole_file_starts_with_the_generated_header(self):
        """source: a whole-file view says at the top that it is generated"""
        self.write_org(sample())
        proc = self.render()
        self.assertEqual(proc.returncode, 0, proc.stdout)
        with open(os.path.join(self.tmp, "ROSTER.md"), encoding="utf-8") as handle:
            text = handle.read()
        self.assertTrue(text.startswith(HEADER + "\n\n# Roster: Fixture Co\n"))
        self.assertTrue(text.endswith("\n"))
        with open(os.path.join(self.tmp, "OWNERS.md"), encoding="utf-8") as handle:
            owners = handle.read()
        self.assertIn("# Who owns what: Fixture Co\n", owners)

    def test_block_keeps_bytes_outside_the_markers(self):
        """source: a block view replaces only the bytes between its two marker lines"""
        page = os.path.join(self.tmp, "PAGE.md")
        with open(page, "w", encoding="utf-8", newline="\n") as handle:
            handle.write("KEEP-BEFORE\n<!-- org:roster:begin -->\nold line\n<!-- org:roster:end -->\nKEEP-AFTER\n")
        data = sample()
        data["outputs"] = [{"view": "roster", "file": "PAGE.md", "block": "roster"}]
        self.write_org(data)
        proc = self.render()
        self.assertEqual(proc.returncode, 0, proc.stdout)
        self.assertIn("wrote PAGE.md (block roster)", proc.stdout)
        with open(page, encoding="utf-8") as handle:
            text = handle.read()
        self.assertTrue(text.startswith("KEEP-BEFORE\n"))
        self.assertTrue(text.endswith("KEEP-AFTER\n"))
        self.assertNotIn("old line", text)
        self.assertIn("Edits between these two markers are overwritten.", text)
        self.assertIn("| Trade |", text)

    def test_a_missing_block_writes_nothing(self):
        """source: when one output cannot be produced, no earlier output is written"""
        path = os.path.join(self.tmp, "ROSTER.md")
        with open(path, "w", encoding="utf-8", newline="\n") as handle:
            handle.write("ORIGINAL\n")
        data = sample()
        data["outputs"] = [
            {"view": "roster", "file": "ROSTER.md"},
            {"view": "roster", "file": "MISSING.md", "block": "roster"},
        ]
        self.write_org(data)
        proc = self.render()
        self.assertEqual(proc.returncode, 2, proc.stdout + proc.stderr)
        self.assertIn("could not render: MISSING.md has no org:roster block", proc.stdout)
        with open(path, encoding="utf-8") as handle:
            self.assertEqual(handle.read(), "ORIGINAL\n")
        self.assertFalse(os.path.exists(os.path.join(self.tmp, "MISSING.md")))

    def test_root_flag_selects_the_folder(self):
        """source: the root flag selects the folder that holds the source file"""
        self.write_org(sample())
        elsewhere = tempfile.mkdtemp(prefix="org-chart-cwd-")
        self.addCleanup(shutil.rmtree, elsewhere)
        env = os.environ.copy()
        env["HOME"] = elsewhere
        env["PYTHONDONTWRITEBYTECODE"] = "1"
        proc = subprocess.run(
            [sys.executable, os.path.join(PROJECT, "render.py"), "--view", "roster", "--root", self.tmp],
            cwd=elsewhere,
            env=env,
            capture_output=True,
            text=True,
        )
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)
        self.assertIn("| Trade |", proc.stdout)
        self.assertNotIn("| Build |", proc.stdout)

    def test_permissions_are_kept(self):
        """source: a render keeps the mode of a file that already exists, and a new file follows the umask"""
        data = sample()
        data["outputs"].append({"view": "roster", "file": "NEW.md"})
        self.write_org(data)
        roster = os.path.join(self.tmp, "ROSTER.md")
        owners = os.path.join(self.tmp, "OWNERS.md")
        with open(roster, "w", encoding="utf-8", newline="\n") as handle:
            handle.write("STALE ROSTER\n")
        os.chmod(roster, 0o640)
        with open(owners, "w", encoding="utf-8", newline="\n") as handle:
            handle.write("STALE OWNERS\n")
        os.chmod(owners, 0o644)
        proc = self.render(umask="022")
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)
        self.assertEqual(proc.stderr, "")
        with open(roster, encoding="utf-8") as handle:
            roster_text = handle.read()
        with open(owners, encoding="utf-8") as handle:
            owners_text = handle.read()
        new = os.path.join(self.tmp, "NEW.md")
        with open(new, encoding="utf-8") as handle:
            new_text = handle.read()
        self.assertNotIn("STALE", roster_text)
        self.assertNotIn("STALE", owners_text)
        self.assertTrue(roster_text.startswith(HEADER + "\n"))
        self.assertTrue(owners_text.startswith(HEADER + "\n"))
        self.assertTrue(new_text.startswith(HEADER + "\n"))
        self.assertEqual(stat.S_IMODE(os.stat(roster).st_mode), 0o640)
        self.assertEqual(stat.S_IMODE(os.stat(owners).st_mode), 0o644)
        self.assertEqual(stat.S_IMODE(os.stat(new).st_mode), 0o644)

    def test_missing_folders_are_made(self):
        """source: folders on the way to an output are created"""
        data = sample()
        data["outputs"] = [{"view": "roster", "file": "docs/team/ROSTER.md"}]
        self.write_org(data)
        proc = self.render(umask="022")
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)
        self.assertEqual(proc.stderr, "")
        self.assertIn("wrote docs/team/ROSTER.md", proc.stdout)
        path = os.path.join(self.tmp, "docs", "team", "ROSTER.md")
        with open(path, encoding="utf-8") as handle:
            self.assertTrue(handle.read().startswith(HEADER + "\n"))
        proc = self.render("--check", umask="022")
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)
        self.assertEqual(proc.stderr, "")

    def test_an_output_that_is_a_folder_stops(self):
        """source: an output that names a folder stops the render and the check"""
        os.makedirs(os.path.join(self.tmp, "docs"))
        data = sample()
        data["outputs"] = [{"view": "roster", "file": "docs"}]
        self.write_org(data)
        proc = self.render(umask="022")
        self.assertEqual(proc.returncode, 2, proc.stdout + proc.stderr)
        self.assertEqual(proc.stdout, "could not render: docs is a folder\n")
        self.assertEqual(proc.stderr, "")
        proc = self.render("--check", umask="022")
        self.assertEqual(proc.returncode, 2, proc.stdout + proc.stderr)
        self.assertEqual(proc.stdout, "could not check: docs is a folder\n")
        self.assertEqual(proc.stderr, "")
        self.assertEqual(self.render_temps(), [])

    def test_a_failed_write_changes_nothing(self):
        """source: a write that fails leaves every earlier file as it was and names the file that could not be written"""
        with open(os.path.join(self.tmp, "notes.txt"), "w", encoding="utf-8", newline="\n") as handle:
            handle.write("notes\n")
        roster = os.path.join(self.tmp, "ROSTER.md")
        with open(roster, "w", encoding="utf-8", newline="\n") as handle:
            handle.write("STALE ROSTER\n")
        with open(roster, "rb") as handle:
            before = handle.read()
        data = sample()
        data["outputs"] = [
            {"view": "roster", "file": "ROSTER.md"},
            {"view": "roster", "file": "notes.txt/ROSTER.md"},
        ]
        self.write_org(data)
        proc = self.render(umask="022")
        self.assertEqual(proc.returncode, 2, proc.stdout + proc.stderr)
        self.assertRegex(
            proc.stdout,
            r"^could not render: notes.txt/ROSTER.md could not be written \(.+\)\n$",
        )
        self.assertEqual(proc.stderr, "")
        with open(roster, "rb") as handle:
            self.assertEqual(handle.read(), before)
        self.assertEqual(self.render_temps(), [])

    def test_a_view_you_add_gets_no_borrowed_title(self):
        """source: a whole file of a view added to VIEWS carries no title of a built-in view"""
        source = os.path.join(PROJECT, "render.py")
        copy_path = os.path.join(self.tmp, "render.py")
        shutil.copy(source, copy_path)
        with open(copy_path, encoding="utf-8") as handle:
            text = handle.read()
        anchor = 'VIEWS = {"roster": view_roster, "owners": view_owners}\n'
        self.assertEqual(text.count(anchor), 1)
        added = """def view_openings(org):
    lines = ["# Openings"]
    for team in org["teams"]:
        head = team["head"]
        line = team["name"] + " (head " + head + ")"
        lines.append(line)
    body = "\\n".join(lines)
    return body + "\\n"

VIEWS["openings"] = view_openings
"""
        text = text.replace(anchor, anchor + added, 1)
        with open(copy_path, "w", encoding="utf-8", newline="\n") as handle:
            handle.write(text)
        data = sample()
        data["outputs"] = [{"view": "openings", "file": "OPENINGS.md"}]
        self.write_org(data)
        proc = self.run_render(copy_path)
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)
        expected = HEADER + "\n\n# Openings\n" + "".join(
            team["name"] + " (head " + team["head"] + ")\n" for team in data["teams"]
        )
        with open(os.path.join(self.tmp, "OPENINGS.md"), encoding="utf-8") as handle:
            self.assertEqual(handle.read(), expected)
        checked = self.run_render(copy_path, "--check")
        self.assertEqual(checked.returncode, 0, checked.stdout + checked.stderr)
        self.assertIn("views match org.json (1 outputs)", checked.stdout)


if __name__ == "__main__":
    unittest.main()
